            if re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", line):
                logging_util.emit_kv(line.split("=", 1)[0], line.split("=", 1)[1])
            else:
                logging_util.emit(line)
        return result.returncode
    except SystemExit as exc:
        return int(exc.code)


